import numpy as np
import re

def run_benchmark(model, dataset, task_type='multiple_choice'):
    correct = 0
    for sample in dataset:
        if task_type == 'multiple_choice':
            prompt = f"Question: {sample['question']}\nOptions: {sample['options']}\nAnswer:"
            response = model(prompt)
            pred = re.search(r'[A-D]', response)
            pred = pred.group() if pred else 'A'
            if pred == sample['answer']:
                correct += 1
        elif task_type == 'math':
            prompt = f"Solve: {sample['question']}"
            response = model(prompt)
            pred = re.search(r'\d+\.?\d*', response)
            if pred and float(pred.group()) == sample['answer']:
                correct += 1
    return correct / len(dataset)
